import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new ctx.THREE.Group();
  root.userData.handlers = {};

  const cleanupTasks = [];

  // Load GLB mesh
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
      // Dispose resources on cleanup
      cleanupTasks.push(() => {
        gltf.scene.traverse((obj) => {
          if (obj.isMesh) {
            if (obj.geometry) obj.geometry.dispose();
            if (obj.material) {
              if (Array.isArray(obj.material)) {
                obj.material.forEach((m) => m.dispose());
              } else {
                obj.material.dispose();
              }
            }
          }
        });
      });
    });
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (fn) {
        const instance = fn(root, primitive.params || {});
        cleanupTasks.push(() => {
          if (instance && typeof instance.cleanup === 'function') instance.cleanup();
        });
      }
    });
  }

  // Hover effect: rise-in (subtle, 0.15 scene units)
  root.userData.handlers.hover = () => {
    // Kill any existing hover timeline
    if (root.userData._hoverTimeline) root.userData._hoverTimeline.kill();
    const tl = gsap.timeline({
      defaults: { duration: 0.7, ease: 'power3.out' },
    });
    tl.to(root.position, { y: root.position.y + 0.15 });
    root.userData._hoverTimeline = tl;
  };

  // Click effect: emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-journal' });
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    cleanupTasks.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        // ignore cleanup errors
      }
    });
    if (root.userData._hoverTimeline) {
      root.userData._hoverTimeline.kill();
    }
  };

  return root;
}
